function routingModule(id){const f={acl:aclLab,standard:aclLab,extended:aclLab,'acl-sim':aclLab,prefix:prefixLab,policy:prefixLab,'ospf-filter':prefixLab,topology:topologyLab,stp:stpLab,election:electionLab,area:ospfAreaLab,stub:ospfAreaLab,'link-types':linkTypesLab,'ospf-path':ospfPathLab,'bgp-best':bgpBestLab,'bgp-select':bgpBestLab,'next-hop':nextHopLab,community:communityLab,regex:regexLab,'as-regex':regexLab,convergence:convergenceLab,lsa:lsaLab,routes:routesLab,show:showLab,decoder:decoderLab};if(!f[id])return false;f[id](id);return true;}
function aclLab(id){let rules=[],standard=id==='standard',config='';$('surface').innerHTML=`<div class="grid equal"><div>${card('Add a rule',`<div class="fields">${select('acl-type','Type',['Extended','Standard'])}${input('acl-name','ACL name','PARAM-LAB')}${select('acl-action','Action',['permit','deny'])}${select('acl-protocol','Protocol',['ip','tcp','udp','icmp'])}</div><div class="fields">${input('acl-src','Source (CIDR or any)','192.168.10.0/24')}${input('acl-dst','Destination (CIDR or any)','any')}${input('acl-port','Destination port (blank = any)','','number','min="1" max="65535"')}</div>${btn('acl-add','Add rule',true)}`)}${card('Test a packet',`<div class="fields">${input('test-src','Source IP','192.168.10.33')}${input('test-dst','Destination IP','203.0.113.10')}${select('test-proto','Protocol',['tcp','udp','icmp'])}${input('test-port','Destination port',443,'number')}</div>${btn('acl-test','Evaluate top down',true)}${out()}`)}</div><div>${card('Ordered rule list',out('acl-rules'))}${card('Generated IOS configuration',`<div class="actions">${btn('acl-copy','Copy config')}${btn('acl-save','Download config')}${btn('acl-clear','Clear rules')}</div>${out('acl-config')}`)}</div></div>`;$('acl-type').value=standard?'Standard':'Extended';const parse=s=>s.trim()==='any'?Net.subnet('0.0.0.0/0'):Net.subnet(s.trim());const match=(s,ip)=>{const n=parse(s),v=Net.ip(ip);return v>=n.start&&v<=n.end;};const cli=s=>{const n=parse(s);return n.p===0?'any':n.p===32?'host '+n.network:n.network+' '+n.wildcard;};const draw=()=>{config=`ip access-list ${standard?'standard':'extended'} ${$('acl-name').value}\n`+rules.map((r,i)=>` ${10*(i+1)} ${r.action} ${standard?'':r.proto+' '}${cli(r.src)}${standard?'':' '+cli(r.dst)+(r.port?' eq '+r.port:'')}`).join('\n');$('acl-rules').innerHTML=rules.length?table(['Seq','Action','Source','Destination','Protocol','Port',''],rules.map((r,i)=>[10*(i+1),r.action,esc(r.src),standard?'—':esc(r.dst),standard?'—':r.proto,r.port||'any',`<button data-remove="${i}">Remove</button>`])):hint('No entries. An empty applied ACL and a configured ACL with rules have different behavior on devices; add rules to test this model.');$('acl-config').innerHTML=`<pre>${esc(config)}</pre>`+hint('Evaluation stops at the first match. This teaching model applies an implicit deny to unmatched packets.');$('acl-rules').querySelectorAll('button').forEach(b=>b.onclick=()=>{rules.splice(Number(b.dataset.remove),1);draw();});};action('acl-add',()=>{if(!/^[A-Za-z][A-Za-z0-9_-]{0,40}$/.test($('acl-name').value))throw Error('Use a simple ACL name starting with a letter.');const src=$('acl-src').value,dst=$('acl-dst').value,p=$('acl-port').value,proto=$('acl-protocol').value;parse(src);parse(dst);if(p&&(!Number.isInteger(Number(p))||Number(p)<1||Number(p)>65535||!['tcp','udp'].includes(proto)))throw Error('A port requires TCP/UDP and a value 1–65535.');rules.push({src,dst,port:p?Number(p):null,proto,action:$('acl-action').value});draw();});action('acl-test',()=>{const src=$('test-src').value,dst=$('test-dst').value,p=Number($('test-port').value),proto=$('test-proto').value;Net.ip(src);Net.ip(dst);if(!Number.isInteger(p)||p<1||p>65535)throw Error('Use a destination port 1–65535.');const index=rules.findIndex(r=>match(r.src,src)&&(standard||(match(r.dst,dst)&&(r.proto==='ip'||r.proto===proto)&&(!r.port||r.port===p))));$('output').innerHTML=stats([['Decision',index<0?'DENY':rules[index].action.toUpperCase(),index>=0&&rules[index].action==='permit'?'highlight':''],['Matched rule',index<0?'Implicit deny':'Sequence '+10*(index+1)]])+hint(index<0?'No configured rule matches all required fields.':`Rule ${10*(index+1)} is the first match; later entries are not evaluated.`);});$('acl-type').onchange=()=>{standard=$('acl-type').value==='Standard';rules=[];draw();};action('acl-copy',()=>copy(config));action('acl-save',()=>download('param-acl.txt',config));action('acl-clear',()=>{rules=[];draw();});draw();}
function prefixLab(id){let entries=[],text='';$('surface').innerHTML=card('Prefix-list entry',`<div class="fields">${input('pl-seq','Sequence',10,'number')}${select('pl-action','Action',['permit','deny'])}${input('pl-network','Prefix','10.0.0.0/8')}${input('pl-ge','ge (optional)','','number')}${input('pl-le','le (optional)',24,'number')}</div>${btn('pl-add','Add entry',true)}${out('pl-list')}`)+card('Test prefix and route-map action',`<div class="fields">${input('pl-test','Test prefix','10.1.2.0/24')}${input('pl-lp','Set local preference',200,'number')}${input('pl-med','Set MED',0,'number')}</div><div class="actions">${btn('pl-evaluate','Evaluate policy',true)}${btn('pl-copy','Copy configuration')}</div>${out()}`);const draw=()=>{$('pl-list').innerHTML=table(['Seq','Action','Prefix','ge','le',''],entries.map((e,i)=>[e.seq,e.action,e.b.cidr,e.ge??'—',e.le??'—',`<button data-del="${i}">Remove</button>`]));$('pl-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{entries.splice(Number(b.dataset.del),1);draw();});text=entries.map(e=>`ip prefix-list PARAM-PREFIXES seq ${e.seq} ${e.action} ${e.b.cidr}${e.ge!==null?' ge '+e.ge:''}${e.le!==null?' le '+e.le:''}`).join('\n');};action('pl-add',()=>{const b=Net.subnet($('pl-network').value),seq=Number($('pl-seq').value),ge=$('pl-ge').value===''?null:Number($('pl-ge').value),le=$('pl-le').value===''?null:Number($('pl-le').value);if(!Number.isInteger(seq)||seq<1||entries.some(e=>e.seq===seq))throw Error('Sequence must be a unique positive integer.');if((ge!==null&&(!Number.isInteger(ge)||ge<=b.p||ge>32))||(le!==null&&(!Number.isInteger(le)||le<b.p||le>32))||(ge!==null&&le!==null&&ge>le))throw Error('Length qualifiers must satisfy base ≤ le ≤ 32, base < ge ≤ 32 and ge ≤ le.');entries.push({b,seq,ge,le,action:$('pl-action').value});entries.sort((a,b)=>a.seq-b.seq);draw();$('pl-seq').value=seq+10;});action('pl-evaluate',()=>{const t=Net.subnet($('pl-test').value),lp=Number($('pl-lp').value),med=Number($('pl-med').value);if(![lp,med].every(x=>Number.isInteger(x)&&x>=0&&x<=4294967295))throw Error('Attributes must be unsigned 32-bit integers.');const e=entries.find(e=>{const min=e.ge??e.b.p,max=e.le??(e.ge!==null?32:e.b.p);return t.start>=e.b.start&&t.end<=e.b.end&&t.p>=min&&t.p<=max;});const allowed=e?.action==='permit';$('output').innerHTML=stats([['Decision',allowed?'PERMIT':'DENY'],['Matched sequence',e?.seq||'Implicit deny']])+`<pre>${esc(text)}\n\nroute-map PARAM-POLICY permit 10\n match ip address prefix-list PARAM-PREFIXES\n set local-preference ${lp}\n set metric ${med}</pre>`+hint(id==='ospf-filter'?'OSPF distribute-list filtering affects local RIB installation; it does not generally stop intra-area LSA flooding. Area filter-list controls Type 3 summaries at ABRs.':'A prefix-list is a match condition. A route-map must be applied in the appropriate direction to a neighbor to affect policy.');});action('pl-copy',()=>copy(text+`\nroute-map PARAM-POLICY permit 10\n match ip address prefix-list PARAM-PREFIXES\n set local-preference ${$('pl-lp').value}\n set metric ${$('pl-med').value}`));$('pl-add').click();$('pl-evaluate').click();}
function topologyLab() {let count=4,links=[{a:0,b:1,cost:10},{a:1,b:2,cost:10},{a:0,b:2,cost:30},{a:2,b:3,cost:5},{a:1,b:3,cost:40}],config='';$('surface').innerHTML=card('Topology editor',`<div class="fields">${select('topo-preset','Preset',['Diamond','Triangle','Ring','Hub and spoke'])}${select('spf-source','Calculate from',['R1','R2','R3','R4'])}</div><div class="actions">${btn('topo-add','Add router')}${btn('spf','Run SPF',true)}${btn('topo-export','Export interface plan')}</div>${out('topo-view')}<div id="links"></div><div class="fields">${input('link-a','Router A number',1,'number')}${input('link-b','Router B number',4,'number')}${input('link-cost','OSPF cost',10,'number')}</div>${btn('link-add','Add link')}`)+card('Shortest path result',out());const draw=()=>{$('topo-view').innerHTML=`<div class="topology">${Array.from({length:count},(_,i)=>`<button class="node" data-router="${i}">R${i+1}<small>AREA 0</small></button>`).join('')}</div>`;$('links').innerHTML=table(['Link','Cost','Failed',''],links.map((l,i)=>[`R${l.a+1} ↔ R${l.b+1}`,`<input type="number" min="1" max="65535" value="${l.cost}" data-cost="${i}" aria-label="Cost of link ${i+1}">`,`<input type="checkbox" data-down="${i}" ${l.down?'checked':''} aria-label="Fail link ${i+1}">`,`<button data-delete="${i}">Remove</button>`]));$('links').querySelectorAll('[data-cost]').forEach(b=>b.onchange=()=>safe(()=>{const c=Number(b.value);if(!Number.isInteger(c)||c<1||c>65535)throw Error('OSPF cost must be 1–65535.');links[Number(b.dataset.cost)].cost=c;calculate();}));$('links').querySelectorAll('[data-down]').forEach(b=>b.onchange=()=>{links[Number(b.dataset.down)].down=b.checked;calculate();});$('links').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{links.splice(Number(b.dataset.delete),1);draw();calculate();});$('topo-view').querySelectorAll('[data-router]').forEach(b=>b.onclick=()=>{$('spf-source').value='R'+(Number(b.dataset.router)+1);calculate();});};const calculate=()=>{const s=Number($('spf-source').value.slice(1))-1,r=Net.spf(count,links,s);$('output').innerHTML=table(['Destination','Cost','Path'],r.dist.map((d,i)=>{let p=[i],n=i;while(r.prev[n]!==null){n=r.prev[n];p.unshift(n);}return['R'+(i+1),d===Infinity?'Unreachable':d,d===Infinity?'—':p.map(x=>'R'+(x+1)).join(' → ')];}));config=links.map((l,i)=>`! R${l.a+1} ↔ R${l.b+1}, link ${i+1}\n! Apply to the appropriate interface on each endpoint:\nip ospf 1 area 0\nip ospf cost ${l.cost}${l.down?'\n! link currently failed in simulation':''}`).join('\n\n');};action('spf',calculate);$('spf-source').onchange=calculate;action('topo-add',()=>{if(count>=12)throw Error('This workspace supports up to 12 routers.');count++;$('spf-source').insertAdjacentHTML('beforeend',`<option>R${count}</option>`);draw();calculate();});action('link-add',()=>{const a=Number($('link-a').value)-1,b=Number($('link-b').value)-1,cost=Number($('link-cost').value);if(![a,b,cost].every(Number.isInteger)||a<0||a>=count||b<0||b>=count||a===b||cost<1||cost>65535)throw Error('Use two different existing router numbers and a cost 1–65535.');if(links.some(l=>(l.a===a&&l.b===b)||(l.a===b&&l.b===a)))throw Error('That link already exists.');links.push({a,b,cost});draw();calculate();});$('topo-preset').onchange=()=>{const p=$('topo-preset').value;if(p==='Triangle'){count=3;links=[{a:0,b:1,cost:10},{a:1,b:2,cost:10},{a:0,b:2,cost:30}];}else{count=4;links=p==='Ring'?[{a:0,b:1,cost:10},{a:1,b:2,cost:10},{a:2,b:3,cost:10},{a:3,b:0,cost:10}]:p==='Hub and spoke'?[{a:0,b:1,cost:10},{a:0,b:2,cost:10},{a:0,b:3,cost:10}]:[{a:0,b:1,cost:10},{a:1,b:2,cost:10},{a:0,b:2,cost:30},{a:2,b:3,cost:5},{a:1,b:3,cost:40}];}$('spf-source').innerHTML=Array.from({length:count},(_,i)=>`<option>R${i+1}</option>`).join('');draw();calculate();};action('topo-export',()=>download('param-ospf-interface-plan.txt',config));draw();calculate();}
function stpLab(){$('surface').innerHTML=card('Three-switch triangle',`<div class="fields">${input('stp-p1','SW1 priority',32768,'number','step="4096"')}${input('stp-p2','SW2 priority',24576,'number','step="4096"')}${input('stp-p3','SW3 priority',32768,'number','step="4096"')}${select('stp-mode','Protocol',['STP','RSTP'])}</div><div class="fields">${input('stp-c12','SW1–SW2 cost',4,'number')}${input('stp-c23','SW2–SW3 cost',4,'number')}${input('stp-c13','SW1–SW3 cost',19,'number')}</div>${btn('stp-run','Elect and calculate',true)}${out()}`);action('stp-run',()=>{const priorities=[1,2,3].map(i=>Number($('stp-p'+i).value));if(priorities.some(p=>!Number.isInteger(p)||p<0||p>61440||p%4096))throw Error('Bridge priorities must be multiples of 4096 from 0 to 61440.');const costs=['12','23','13'].map(x=>Number($('stp-c'+x).value));if(costs.some(c=>!Number.isInteger(c)||c<1))throw Error('Path costs must be positive integers.');let root=priorities.indexOf(Math.min(...priorities)),links=[{a:0,b:1,cost:costs[0]},{a:1,b:2,cost:costs[1]},{a:0,b:2,cost:costs[2]}],r=Net.spf(3,links,root);$('output').innerHTML=stats([['Root bridge','SW'+(root+1)],['Protocol',$('stp-mode').value]])+table(['Switch','Root path cost','Root port toward'],r.dist.map((c,i)=>['SW'+(i+1),c,i===root?'Root bridge':'SW'+(r.prev[i]+1)]))+table(['Segment','Endpoint role A','Endpoint role B'],links.map(l=>{const dp=r.dist[l.a]<r.dist[l.b]?l.a:r.dist[l.b]<r.dist[l.a]?l.b:priorities[l.a]<=priorities[l.b]?l.a:l.b;return[`SW${l.a+1} ↔ SW${l.b+1}`,r.prev[l.a]===l.b?'Root':dp===l.a?'Designated':$('stp-mode').value==='RSTP'?'Alternate / discarding':'Blocking',r.prev[l.b]===l.a?'Root':dp===l.b?'Designated':$('stp-mode').value==='RSTP'?'Alternate / discarding':'Blocking'];}))+hint('This triangle uses unique fixed MACs ordered SW1 < SW2 < SW3 for bridge-ID ties. Production tie-breaking also considers sender bridge and port identifiers. RSTP uses discarding, learning and forwarding states.');});$('stp-run').click();}
function electionLab(){let incumbent=null;$('surface').innerHTML=card('Broadcast-network election',`<div class="fields">${[1,2,3,4].map(i=>input('dr-'+i,'R'+i+' priority',i===2?100:i===3?50:1,'number','min="0" max="255"')).join('')}</div><div class="actions">${btn('elect','Run new election',true)}${btn('dr-arrival','Evaluate newcomer')}${btn('dr-fail','Fail current DR')}</div>${out()}`);const eligible=()=>[1,2,3,4].map(i=>({i,p:Number($('dr-'+i).value)})).filter(x=>x.p>0).sort((a,b)=>b.p-a.p||b.i-a.i);const validate=()=>{for(let i=1;i<=4;i++){const p=Number($('dr-'+i).value);if(!Number.isInteger(p)||p<0||p>255)throw Error('Priority must be 0–255.');}};let dr=null,bdr=null;const draw=message=>{$('output').innerHTML=stats([['DR',dr?'R'+dr:'None'],['BDR',bdr?'R'+bdr:'None']])+table(['Router','RID','Priority','Role'],[1,2,3,4].map(i=>['R'+i,`${i}.${i}.${i}.${i}`,$('dr-'+i).value,i===dr?'DR':i===bdr?'BDR':Number($('dr-'+i).value)===0?'Ineligible':'DROther']))+hint(message);};action('elect',()=>{validate();const a=eligible();dr=a[0]?.i;bdr=a[1]?.i;incumbent=dr;draw('Fresh election: highest priority wins; highest router ID breaks a tie. Priority 0 is ineligible.');});action('dr-arrival',()=>{validate();const a=eligible();if(!dr){dr=a[0]?.i;bdr=a[1]?.i;}draw('A healthy DR is not preempted by a higher-priority newcomer. Clear/restart adjacency only when operationally justified.');});action('dr-fail',()=>{const old=dr;dr=bdr;bdr=eligible().filter(x=>x.i!==old&&x.i!==dr)[0]?.i;draw('The BDR is promoted when the DR fails. Another eligible router becomes BDR.');});$('elect').click();}
const OSPF_AREAS={Standard:{types:[1,2,3,4,5],external:'Type 5',default:'Optional'},Stub:{types:[1,2,3],external:'Blocked',default:'Type 3 from ABR'},'Totally stubby':{types:[1,2],external:'Blocked',default:'Type 3 default only'},NSSA:{types:[1,2,3,7],external:'Local Type 7',default:'Conditional / configuration dependent'},'Totally NSSA':{types:[1,2,7],external:'Local Type 7',default:'Type 3 default from ABR'}};
function ospfAreaLab(){$('surface').innerHTML=card('Area behavior',select('area-type','Area type',Object.keys(OSPF_AREAS))+out())+card('Compare all types',table(['Area','Ordinary LSAs','External redistribution','Default route'],Object.entries(OSPF_AREAS).map(([k,v])=>[k,v.types.join(', '),v.external,v.default])));const draw=()=>{const t=$('area-type').value,a=OSPF_AREAS[t];$('output').innerHTML=stats([['Selected area',t],['Ordinary LSA types',a.types.join(', ')],['External reachability',a.external],['Default',a.default]])+hint('The lists exclude the special default-route exception. Totally stubby and totally NSSA are vendor extensions. NSSA Type 7 LSAs can be translated by an eligible ABR into Type 5 outside the NSSA.')+`<pre>${t==='Standard'?'! No stub/NSSA area command':t==='Stub'?'area 1 stub':t==='Totally stubby'?'area 1 stub no-summary':t==='NSSA'?'area 1 nssa':'area 1 nssa no-summary'}</pre>`;};$('area-type').onchange=draw;draw();}
function linkTypesLab(){const data={'Broadcast':['Yes','Yes','10 / 40','Ethernet shared segment'],'Point-to-point':['No','No','10 / 40','Two endpoints; both can become Full'],NBMA:['Yes','Usually manual','30 / 120','Non-broadcast multi-access'],'Point-to-multipoint':['No','No (if multicast supported)','30 / 120','Models a set of point-to-point adjacencies'],'Point-to-multipoint non-broadcast':['No','Manual','30 / 120','Explicit neighbors needed']};$('surface').innerHTML=card('OSPF network type',select('link-type','Select network type',Object.keys(data))+out())+hint('Values shown are common Cisco IOS defaults. Always inspect the actual interface configuration and platform defaults.');const run=()=>{const d=data[$('link-type').value];$('output').innerHTML=stats([['DR/BDR election',d[0]],['Manual neighbors',d[1]],['Hello / dead (seconds)',d[2]],['Behavior',d[3]]]);};$('link-type').onchange=run;run();}
function ospfPathLab(){$('surface').innerHTML=card('Two candidate OSPF routes',`<div class="fields">${select('op-a','Route A type',['O','O IA','E1','N1','E2','N2'])}${input('op-ac','A external / route metric',20,'number')}${input('op-ai','A internal cost to exit',100,'number')}</div><div class="fields">${select('op-b','Route B type',['O','O IA','E1','N1','E2','N2'])}${input('op-bc','B external / route metric',10,'number')}${input('op-bi','B internal cost to exit',5,'number')}</div>${btn('ospf-choose','Select path',true)}${out()}`);$('op-b').value='E2';action('ospf-choose',()=>{const a=$('op-a').value,b=$('op-b').value,ca=Number($('op-ac').value),cb=Number($('op-bc').value),ia=Number($('op-ai').value),ib=Number($('op-bi').value);if([ca,cb,ia,ib].some(x=>!Number.isInteger(x)||x<0))throw Error('Costs must be nonnegative integers.');const rank={O:0,'O IA':1,E1:2,N1:2,E2:3,N2:3},score=(t,c,i)=>['E1','N1'].includes(t)?c+i:c;let winner,reason;if(rank[a]!==rank[b]){winner=rank[a]<rank[b]?'A':'B';reason='Route type preference';}else{const va=score(a,ca,ia),vb=score(b,cb,ib);if(va!==vb){winner=va<vb?'A':'B';reason='Metric comparison';}else if(['E2','N2'].includes(a)&&['E2','N2'].includes(b)&&ia!==ib){winner=ia<ib?'A':'B';reason='Equal type-2 metric; compare internal cost';}else{winner='Equal in this model';reason='Additional platform rules or ECMP apply';}}$('output').innerHTML=stats([['Preferred candidate',winner,'highlight'],['Reason',reason],['A comparison metric',score(a,ca,ia)],['B comparison metric',score(b,cb,ib)]])+hint('The model assumes valid routes to the same prefix. Intra-area wins over inter-area, then type-1 external over type-2. NSSA translation, RFC 1583 compatibility and vendor tie-breaks can add rules.');});$('ospf-choose').click();}
function bgpBestLab(){$('surface').innerHTML=card('Candidate attributes',table(['Attribute','Path A','Path B'],[['Weight','weight',0,0],['Local preference','localPref',100,100],['Locally originated (1=yes)','local',0,0],['AS-path length','pathLength',2,3],['Origin (0=IGP, 1=EGP, 2=incomplete)','origin',0,0],['MED (same neighboring AS)','med',50,100],['iBGP (1=yes; eBGP=0)','ibgp',0,0],['IGP cost to next hop','igp',10,20],['Router ID final tie-break (numeric)','routerId',1,2]].map(([label,key,a,b])=>[label,`<input id="bgp-a-${key}" aria-label="Path A ${label}" type="number" min="0" value="${a}">`,`<input id="bgp-b-${key}" aria-label="Path B ${label}" type="number" min="0" value="${b}">`]))+`<div class="fields"><label><input id="bgp-a-reach" type="checkbox" checked> Path A next hop reachable</label><label><input id="bgp-b-reach" type="checkbox" checked> Path B next hop reachable</label></div>${btn('best','Choose best path',true)}${out()}`+hint('This Cisco-style model compares valid paths for one prefix and assumes MED is comparable from the same neighboring AS. Weight is local to a router. Some production tie-breaks and multipath rules are outside this model.'));action('best',()=>{const routes=['a','b'].map(k=>{const r={name:k.toUpperCase(),reachable:$('bgp-'+k+'-reach').checked};for(const key of ['weight','localPref','local','pathLength','origin','med','ibgp','igp','routerId']){r[key]=Number($('bgp-'+k+'-'+key).value);if(!Number.isInteger(r[key])||r[key]<0||r[key]>4294967295)throw Error('Use nonnegative 32-bit integer attributes.');}if(r.origin>2||r.ibgp>1||r.local>1)throw Error('Origin must be 0–2; boolean attributes 0 or 1.');return r;});const b=Net.bestBGP(routes);$('output').innerHTML=stats([['Selected path',b.winner.name,'highlight'],['Decisive attribute',routes.filter(r=>r.reachable).length===1?'Next-hop reachability':b.decisive]]);});$('best').click();}
function nextHopLab(){$('surface').innerHTML=card('Advertisement controls',`<div class="fields">${select('nh-source','Advertisement',['eBGP → iBGP','Route reflector → client','Direct eBGP'])}${select('nh-reach','Reachability',['No route to original next hop','IGP route present','Static route present'])}</div><label><input id="nh-self" type="checkbox"> Apply next-hop-self (advertising router loopback is reachable)</label><div class="actions">${btn('nh-evaluate','Evaluate route',true)}</div>${out()}`);action('nh-evaluate',()=>{const direct=$('nh-source').value==='Direct eBGP',self=$('nh-self').checked,reachable=direct||self||$('nh-reach').value!=='No route to original next hop';$('output').innerHTML=stats([['Next hop',self?'10.0.0.1 (advertiser)':'192.0.2.1 (original)'],['Usable path?',reachable?'Yes':'No']])+hint(reachable?'The receiver can recursively resolve the next hop. Other policy and route validity checks still apply.':'The path cannot become a usable forwarding route until the advertised next hop is reachable.')+`<pre>router bgp 65000\n neighbor 10.0.0.2 remote-as 65000${self?'\n neighbor 10.0.0.2 next-hop-self':''}</pre>`;});$('nh-evaluate').click();}
function communityLab(){$('surface').innerHTML=card('Community policy',`<div class="fields">${select('comm','Tag',['no-export','no-advertise','65000:120','65535:666','65000:100:10'])}${select('comm-peer','Recipient',['External peer','Internal peer'])}${select('comm-policy','Recipient policy',['Honor configured tag policy','Ignore policy tag','Strip tag'])}</div>${btn('comm-run','Apply policy',true)}${out()}`);action('comm-run',()=>{const tag=$('comm').value,peer=$('comm-peer').value,policy=$('comm-policy').value;let result='Tag is metadata; no forwarding change by itself.';if(policy==='Strip tag')result='Tag removed before subsequent export.';else if(policy==='Ignore policy tag')result='No configured action for this teaching scenario. Well-known communities should be honored by compliant implementations.';else result=tag==='no-export'?peer==='External peer'?'Do not export outside this AS/confederation.':'May advertise internally.':tag==='no-advertise'?'Do not advertise to any BGP peer.':tag==='65000:120'?'Example route-map sets local preference to 200.':tag==='65535:666'?'Blackhole signaling requires explicit receiver policy and authorization.':'Large community identifies AS / function / parameter; action is policy-defined.';$('output').innerHTML=stats([['Tag',policy==='Strip tag'?'None':tag],['Outcome',result,'full']])+`<pre>route-map PARAM-TAG permit 10\n set ${tag.split(':').length===3?'large-community':'community'} ${esc(tag)} additive</pre>`+hint('Ordinary and large communities carry intent. A matching routing policy determines the action.');});$('comm-run').click();}
function regexLab(){$('surface').innerHTML=card('Cisco AS-path expression',input('regex','Expression','_65001_')+area('paths','AS paths, one per line','65001\n64500 65001\n65010 65011\n64500 65001 65002\n{65001 65002}')+`<div class="chips">${['^$','^65001_','_65001$','_65001_','.*'].map(x=>`<button data-regex="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="actions">${btn('regex-run','Test expression',true)}</div>${out()}`+hint('Cisco _ matches an AS boundary (space, comma, braces, parentheses, beginning or end). This tool converts that boundary to a browser regular expression.'));action('regex-run',()=>{const raw=$('regex').value;if(raw.length>120||/\([^)]*[+*][^)]*\)[+*{]|\([^)]*\|[^)]*\)[+*{]/.test(raw))throw Error('Use a short expression without nested or ambiguous repeated groups.');const regex=new RegExp(raw.replace(/_/g,'(?:^|$|[ ,{}()])'));const lines=$('paths').value.split('\n');if(lines.length>200||lines.some(x=>x.length>250))throw Error('Use at most 200 paths of 250 characters.');$('output').innerHTML=table(['AS path','Match'],lines.map(s=>[esc(s)||'(empty)',regex.test(s)?'<span class="positive">Match</span>':'No match']))+`<pre>ip as-path access-list 10 permit ${esc(raw)}</pre>`;});$('surface').querySelectorAll('[data-regex]').forEach(b=>b.onclick=()=>{$('regex').value=b.dataset.regex;$('regex-run').click();});$('regex-run').click();}
function convergenceLab(){$('surface').innerHTML=card('Convergence phases',`<div class="fields">${select('conv-profile','Preset',['OSPF default','BFD tuned','BGP hold timer','Custom'])}</div><div class="fields">${input('detect','Failure detection (ms)',40000,'number')}${input('schedule','Scheduling (ms)',50,'number')}${input('compute','Computation (ms)',200,'number')}${input('rib','RIB update (ms)',50,'number')}${input('fib','FIB programming (ms)',10,'number')}</div>${btn('conv-run','Estimate convergence',true)}${out()}`);action('conv-run',()=>{const values=['detect','schedule','compute','rib','fib'].map(id=>Number($(id).value));if(values.some(x=>!Number.isFinite(x)||x<0))throw Error('Phase durations must be nonnegative.');const total=values.reduce((a,b)=>a+b,0);$('output').innerHTML=stats([['Estimated total',total.toLocaleString()+' ms','big highlight'],['Seconds',(total/1000).toFixed(3)]])+`<div style="display:flex;height:35px;margin:20px 0">${values.map((v,i)=>`<div title="${v} ms" style="width:${v/(total||1)*100}%;background:${['#74a9ff','#5be0c3','#f4aa76','#ae9fff','#ff938f'][i]}"></div>`).join('')}</div>`+table(['Phase','Duration'],['Failure detection','Scheduling','Computation','RIB install','FIB programming'].map((p,i)=>[p,values[i]+' ms']))+hint('An additive teaching estimate. Actual convergence includes propagation, pacing, CPU load and hardware behavior; some phases overlap.');});$('conv-profile').onchange=()=>{const vals=$('conv-profile').value==='BFD tuned'?[150,10,20,10,10]:$('conv-profile').value==='BGP hold timer'?[180000,0,50,50,10]:[40000,50,200,50,10];['detect','schedule','compute','rib','fib'].forEach((id,i)=>$(id).value=vals[i]);$('conv-run').click();};$('conv-run').click();}
const LSA_INFO={1:['Router','Every router','Area','Links and costs within one area'],2:['Network','DR','Area','Routers attached to a transit network'],3:['Summary','ABR','Inter-area','Reachability to another area'],4:['ASBR summary','ABR','Inter-area','Reachability to an ASBR'],5:['AS external','ASBR','AS (except stub/NSSA)','Redistributed external destination'],6:['Group membership','MOSPF router','Area','Historical multicast OSPF extension'],7:['NSSA external','NSSA ASBR','NSSA area','External destination inside an NSSA'],8:['External attributes','Historical proposal','Historical','Not a commonly deployed OSPFv2 LSA'],9:['Opaque link-local','Extension capable router','Link','Opaque extension data'],10:['Opaque area-local','Extension capable router','Area','Traffic-engineering extension data'],11:['Opaque AS-wide','Extension capable router','AS','Opaque extension data']};
function lsaLab(){$('surface').innerHTML=card('Link-state advertisement explorer',`<div class="fields">${select('lsa-type','LSA type',Object.entries(LSA_INFO).map(([k,v])=>[k,'Type '+k+' — '+v[0]]))}${input('lsa-rid','Advertising router','1.1.1.1')}${input('lsa-age','Age (seconds)',312,'number','min="0" max="3600"')}</div>${btn('lsa-inspect','Inspect LSA',true)}${out()}`)+card('Common header layout',table(['Bytes','Field'],[['2','LS age'],['1','Options'],['1','LS type'],['4','Link State ID'],['4','Advertising router'],['4','Sequence number'],['2','Checksum'],['2','Length']]));action('lsa-inspect',()=>{const t=$('lsa-type').value,v=LSA_INFO[t],age=Number($('lsa-age').value);Net.ip($('lsa-rid').value);if(!Number.isInteger(age)||age<0||age>3600)throw Error('LSA age must be 0–3600 seconds.');$('output').innerHTML=stats([['LSA',v[0]],['Originator',v[1]],['Flooding scope',v[2]],['Purpose',v[3]],['Advertising router',$('lsa-rid').value],['Age status',age===3600?'MaxAge: eligible for flush':age>=1800?'Past usual refresh interval':'Within refresh interval']])+`<pre>show ip ospf database${t==='1'?' router':t==='2'?' network':t==='5'?' external':''}</pre>`;});$('lsa-inspect').click();}
function routesLab(){$('surface').innerHTML=card('Routing table input',area('route-text','Paste CIDR lines or IOS-style routes','C 192.168.10.0/24 is directly connected, GigabitEthernet0/0\nO 10.0.0.0/8 [110/20] via 192.168.10.1\nS* 0.0.0.0/0 [1/0] via 192.168.10.254\nB 203.0.113.0/24 [20/0] via 192.168.10.2')+`<div class="fields">${input('route-ip','Destination lookup','203.0.113.33')}</div>${btn('route-parse','Parse and look up',true)}${out()}`);action('route-parse',()=>{const dest=Net.ip($('route-ip').value),rows=$('route-text').value.split('\n').map(line=>{const m=line.match(/\b(\d+\.\d+\.\d+\.\d+\/\d{1,2})\b/);if(!m)return null;const b=Net.subnet(m[1]);return{b,protocol:line.trim().match(/^[A-Za-z* ]+/)?.[0].trim()||'—',next:line.match(/via\s+([\d.]+)/)?.[1]||'Connected / unspecified',ad:line.match(/\[(\d+)\/(\d+)\]/)?.[1]||'—'};}).filter(Boolean);if(!rows.length)throw Error('No CIDR routes were found. This parser requires explicit prefix lengths.');const matches=rows.filter(r=>dest>=r.b.start&&dest<=r.b.end).sort((a,b)=>b.b.p-a.b.p||Number(a.ad)-Number(b.ad));$('output').innerHTML=stats([['Parsed routes',rows.length],['Longest prefix',matches[0]?.b.cidr||'No route']])+table(['Prefix','Protocol','AD','Next hop'],rows.map(r=>[r===matches[0]?`<strong class="positive">${r.b.cidr}</strong>`:r.b.cidr,esc(r.protocol),r.ad,esc(r.next)]))+hint('CIDR prefixes are recognized directly. IOS classful shorthand without a slash is not inferred. Equal-prefix routes require the full RIB selection rules.');});$('route-parse').click();}
function showLab(){$('surface').innerHTML=card('Interpret operational output',`<div class="chips">${['OSPF neighbor','BGP summary','EIGRP topology','IS-IS neighbor','MPLS LFIB'].map(x=>`<button data-show="${x}">${x}</button>`).join('')}</div>`+area('show-text','Command output','Neighbor ID     Pri   State       Dead Time   Address       Interface\n2.2.2.2         1     FULL/DR     00:00:35    10.0.0.2      Gi0/0')+`<div class="actions">${btn('show-analyze','Analyze output',true)}</div>${out()}`);const samples={'OSPF neighbor':'Neighbor ID Pri State Dead Time Address Interface\n2.2.2.2 1 EXSTART/DR 00:00:35 10.0.0.2 Gi0/0','BGP summary':'Neighbor V AS MsgRcvd MsgSent Up/Down State/PfxRcd\n192.0.2.1 4 65001 22 25 00:03:12 Active','EIGRP topology':'IP-EIGRP Topology Table for AS(100)\nP 10.1.0.0/24, 1 successors, FD is 3072\nvia 10.0.0.2 (3072/2816), Gi0/0','IS-IS neighbor':'System Id Type Interface State Holdtime\nR2 L2 Gi0/0 UP 22','MPLS LFIB':'Local Outgoing Prefix Bytes Outgoing Next Hop\n16 Pop Label 10.1.0.0/24 1024 Gi0/0 10.0.0.2'};action('show-analyze',()=>{const s=$('show-text').value;let type='Unknown',flags=[],next=[];if(/Neighbor ID|FULL\/|EXSTART|2WAY/i.test(s)){type='OSPF neighbor';next=['show ip ospf interface','show interfaces','show ip ospf database'];if(/EXSTART|EXCHANGE/i.test(s))flags.push('DBD synchronization incomplete: compare MTU, router IDs and packet exchange.');if(/INIT/i.test(s))flags.push('One-way Hello visibility: inspect ACL/multicast path and neighbor list.');if(/2WAY/i.test(s))flags.push('2-Way can be normal between broadcast DROther routers.');}else if(/State\/PfxRcd|MsgRcvd|BGP/i.test(s)){type='BGP summary';next=['show bgp neighbors','show ip route <peer>','show tcp brief'];if(/Active|Idle|Connect/i.test(s))flags.push('Session is not Established: inspect TCP/179 reachability, remote-AS, update-source and TTL.');}else if(/EIGRP|successors|FD is/i.test(s)){type='EIGRP topology';next=['show ip eigrp neighbors','show ip eigrp topology all-links'];flags.push('P means Passive (stable), not a disabled route. A means Active (diffusing computation).');}else if(/System Id|IS-IS/i.test(s)){type='IS-IS neighbor';next=['show isis neighbors detail','show clns interface'];}else if(/Pop Label|LFIB|Outgoing Prefix/i.test(s)){type='MPLS LFIB';next=['show mpls forwarding-table','show mpls ldp neighbor'];flags.push('Pop Label indicates penultimate-hop popping for the corresponding forwarding entry.');}else flags.push('Format not recognized. Use the samples or inspect the original command documentation.');$('output').innerHTML=stats([['Detected output',type]])+hint(flags.length?flags.map(esc).join('<br>'):'No known warning pattern was detected. This does not prove the device is healthy.')+`<pre>${esc(next.join('\n'))}</pre>`;});$('surface').querySelectorAll('[data-show]').forEach(b=>b.onclick=()=>{$('show-text').value=samples[b.dataset.show];$('show-analyze').click();});$('show-analyze').click();}
function decoderLab(){const sample='02 00 00 00 00 02 02 00 00 00 00 01 08 00 45 00 00 28 00 01 40 00 40 06 00 00 c0 00 02 01 c6 33 64 02 c0 00 01 bb 00 00 03 e8 00 00 00 00 50 02 fa f0 00 00 00 00';$('surface').innerHTML=card('Ethernet packet decoder',area('hex','Hex bytes (Ethernet frame)',sample)+`<div class="actions">${btn('decode','Decode fields',true)}${btn('decode-sample','Load TCP SYN sample')}</div>${out()}`);action('decode',()=>{const text=$('hex').value.trim();if(!/^(?:[0-9a-fA-F]{2}[\s:]*)+$/.test(text))throw Error('Use pairs of hexadecimal digits separated by spaces or colons.');const a=text.match(/[0-9a-fA-F]{2}/g).map(x=>parseInt(x,16));if(a.length<14)throw Error('An Ethernet header requires at least 14 bytes.');if(a.length>65535)throw Error('Use one frame, at most 65535 bytes.');const word=i=>a[i]*256+a[i+1],mac=i=>a.slice(i,i+6).map(x=>x.toString(16).padStart(2,'0')).join(':'),address=i=>a.slice(i,i+4).join('.');let rows=[['Ethernet destination',mac(0)],['Ethernet source',mac(6)],['EtherType','0x'+word(12).toString(16)]];let off=14,type=word(12);if(type===0x8100){if(a.length<18)throw Error('Truncated VLAN frame.');rows.push(['VLAN ID',word(14)&4095]);type=word(16);off=18;}if(type===0x0800){if(a.length<off+20)throw Error('Truncated IPv4 header.');const ihl=(a[off]&15)*4,total=word(off+2);if(a[off]>>4!==4||ihl<20||ihl>60||a.length<off+ihl||total<ihl||a.length<off+total)throw Error('Invalid or truncated IPv4 packet.');const proto=a[off+9],transport=off+ihl,frag=word(off+6)&8191;rows.push(['IPv4 source',address(off+12)],['IPv4 destination',address(off+16)],['IPv4 TTL',a[off+8]],['IPv4 header bytes',ihl],['IP total length',total],['IP protocol',proto],['Fragment offset (8-byte units)',frag]);if(!frag&&(proto===6||proto===17)){const need=proto===6?20:8;if(total<ihl+need)throw Error('Truncated transport header.');rows.push(['Source port',word(transport)],['Destination port',word(transport+2)]);if(proto===6){const seq=transport+4,ack=transport+8,number=i=>a.slice(i,i+4).reduce((n,b)=>n*256+b,0);rows.push(['Sequence',number(seq)],['Acknowledgment',number(ack)],['TCP flags','0x'+a[transport+13].toString(16)],['Window',word(transport+14)]);}}else if(proto===1&&!frag){if(total<ihl+4)throw Error('Truncated ICMP header.');rows.push(['ICMP type',a[transport]],['ICMP code',a[transport+1]]);}else if(proto===89&&!frag){if(total<ihl+24)throw Error('Truncated OSPF header.');rows.push(['OSPF version',a[transport]],['OSPF packet type',a[transport+1]],['Router ID',address(transport+4)],['Area ID',address(transport+8)]);}}else if(type===0x0806){if(a.length<off+28)throw Error('Truncated ARP frame.');rows.push(['ARP opcode',word(off+6)],['Sender MAC',mac(off+8)],['Sender IP',address(off+14)],['Target MAC',mac(off+18)],['Target IP',address(off+24)]);}else rows.push(['Payload','EtherType not decoded in this version']);$('output').innerHTML=table(['Field','Decoded value'],rows)+hint('Ethernet, 802.1Q, IPv4, TCP, UDP, ICMP, ARP and basic OSPF headers are decoded. Checksum validation and complete application payload decoding require a packet analyzer.');});action('decode-sample',()=>{$('hex').value=sample;$('decode').click();});$('decode').click();}
